/// <summary>
/// Class of METRetroDiscountFreeTextInvoicePost
/// </summary>
internal final class METRetroDiscountFreeTextInvoicePost 
{
    private CustAccount             custAccount;
    private CustInvoiceAccount      invoiceAccount;
    private ItemId                  itemId;
    private CurrencyCode            currency;
    private Amount                  freeTextInvoiceAmount;
    private RetailPeriodicDiscount  discount;

    private TransDate               transDateToday;

    private List                    transList;

}

Method.Source:
    /// <summary>
    /// New
    /// </summary>
    /// <param name = "_trans">Transaction</param>
    internal void new(METRetroDiscountSalesInvoiceTransaction _trans)
    {
        this.custAccount    = _trans.CustAccount;
        this.invoiceAccount = _trans.InvoiceAccount;
        this.itemId         = _trans.ItemId;
        this.currency       = _trans.CurrencyCode;
        this.discount       = RetailPeriodicDiscount::findByOfferId(_trans.OfferId);

        this.transDateToday = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

        this.transList      = new List(Types::Int64);

        this.addTransToList(_trans);
    }

/// <summary>
/// Add trans to list
/// </summary>
/// <param name = "_trans">Transaction</param>
internal void addTransToList(METRetroDiscountSalesInvoiceTransaction _trans)
{
    this.freeTextInvoiceAmount += _trans.RetroDiscountAmount;
    transList.addEnd(_trans.RecId);
}

    /// <summary>
    /// postFreeTextInovice
    /// </summary>
    internal void postFreeTextInovice()
    {
        SubledgerJournalEntryNotTransferred subledgerJour;
        CustInvoiceJour custInvoiceJour;
        CustInvoiceTable custInvoiceTable = this.createDocumentHeader(this.transDateToday);
        this.createDocumentLine(custInvoiceTable);

        Args args = new Args();
        args.record(custInvoiceTable);

        CustPostInvoice::main(args);

        custInvoiceTable.reread();
        
        custInvoiceJour = CustInvoiceJour::findFromCustTrans(custInvoiceTable.InvoiceId, custInvoiceTable.InvoiceDate, custInvoiceTable.InvoiceAccount);
        select firstonly subledgerJour where subledgerJour.Voucher == custInvoiceJour.LedgerVoucher;
        
        if (subledgerJour)
        {
            SubledgerJournalEntryTransfer::executeTransfer(subledgerJour);
        }

        this.updateRecordAfterFreeTextInvoicePost(custInvoiceTable.InvoiceId);
    }

    /// <summary>
    /// Update Invoice
    /// </summary>
    /// <param name = "_invoiceId">InvoiceId</param>
    private void updateRecordAfterFreeTextInvoicePost(InvoiceId _invoiceId)
    {
        METRetroDiscountSalesInvoiceTransaction trans;
        ListEnumerator enumerator = this.transList.getEnumerator();

        while (enumerator.moveNext())
        {
            trans = METRetroDiscountSalesInvoiceTransaction::find(enumerator.current(), true);

            trans.Posted = NoYes::Yes;
            trans.RetroPostDate = this.transDateToday;
            trans.RetroInvoice =_invoiceId;

            trans.update();
        }
    }

    /// <summary>
    /// Create Document Header
    /// </summary>
    /// <param name = "_transDate">TransDate</param>
    /// <returns>CustInvoiceTable</returns>
    private CustInvoiceTable createDocumentHeader(TransDate _transDate)
    {
        CustInvoiceTable custInvoiceTable;

        custInvoiceTable.initValue();
        custInvoiceTable.initFromCustTable(CustTable::find(this.CustAccount));

        custInvoiceTable.InvoiceAccount     = this.invoiceAccount;
        custInvoiceTable.InvoiceDate        = _transDate;
        custInvoiceTable.TaxItemGroup       = InventTableModule::find(this.itemId, ModuleInventPurchSales::Sales).TaxItemGroupId;
        custInvoiceTable.CurrencyCode       = this.currency;
        custInvoiceTable.WorkerSalesTaker   = HcmWorker::userId2Worker(curUserId());

        custInvoiceTable.insert();

        return custInvoiceTable;
    }

    /// <summary>
    /// create document line
    /// </summary>
    /// <param name = "_custInvoiceTable">custInvoiceTable</param>
    private void createDocumentLine(CustInvoiceTable _custInvoiceTable)
    {
        CustInvoiceLine custInvoiceLine;

        custInvoiceLine.initValue();
        custInvoiceLine.initFromCustInvoiceTable(_custInvoiceTable);

        custInvoiceLine.ParentRecId     = _custInvoiceTable.RecId;
        custInvoiceLine.LedgerDimension = this.getLedgerDismension();
        custInvoiceLine.TaxItemGroup    = InventTableModule::find(this.itemId, ModuleInventPurchSales::Sales).TaxItemGroupId;
        custInvoiceLine.Description     = '';
        custInvoiceLine.InvoiceTxt      = custInvoiceLine.Description;
        custInvoiceLine.AmountCur       = this.freeTextInvoiceAmount;

        custInvoiceLine.insert();
    }

    /// <summary>
    /// Get ledger dimension
    /// </summary>
    /// <returns>LedgerDimensionDefaultAccount</returns>
    private LedgerDimensionDefaultAccount getLedgerDismension()
    {
        LedgerDimensionDefaultAccount dimension;

        if (discount.DiscountLedgerDimension)
        {
            return discount.DiscountLedgerDimension;
        }

        GUPPriceComponentCodeSetup componentCodeSetup = GUPPriceComponentCodeSetup::findByName(discount.PriceComponentCodeName);

        if (componentCodeSetup.PostingProfileName)
        {
            GUPPriceComponentCodePostingProfile postingProfile;

            select firstonly RecId from postingProfile
                where postingProfile.Name == componentCodeSetup.PostingProfileName;

            GUPPriceComponentCodePostingSearchParameters parameters =
                GUPPriceComponentCodePostingSearchParameters::newFromParameters(
                    postingProfile.RecId,
                    itemId,
                    '',
                    custAccount,
                    '');

            dimension = GUPPriceComponentCodePosting::getLedgerDimensionFromParameters(parameters);
        }

        return dimension ? dimension : RetailPeriodicDiscount::ledgerAccountPeriodicDisc(discount.OfferId, 0, itemId, '', custAccount);
    }
